import java.awt.geom.AffineTransform

// Create and configure an AffineTransform matrix
val transform = new AffineTransform()
transform.translate(100.0, 200.0)
transform.scale(2.0, 3.0)

// Apply the affine transformation to the spatial data generator builder
// BEFORE calling the distribution method (uniform)
val generatedData = sc.generateSpatialData
  .affineTransform(transform)
  .uniform(1000)

// Force materialization and verify the count
val count = generatedData.count()
assert(count == 1000, s"Expected 1000 generated features, but got $count")

// Verify the transformation was applied correctly.
// The default uniform distribution in Beast generates geometries in the unit square [0, 1] x [0, 1].
// After scaling by (2, 3) and translating by (100, 200), all geometries should fall within [100, 102] x [200, 203].
val firstGeom = generatedData.first().getGeometry
val env = firstGeom.getEnvelopeInternal

assert(env.getMinX >= 100.0 && env.getMaxX <= 102.0, s"Expected X in [100, 102], got ${env.getMinX}")
assert(env.getMinY >= 200.0 && env.getMaxY <= 203.0, s"Expected Y in [200, 203], got ${env.getMinY}")

println(s"__CHECK__ affineTransform $count, first geom minX: ${env.getMinX}")

