import org.locationtech.jts.geom.{GeometryFactory, Coordinate}
import edu.ucr.cs.bdlab.beast.cg.Reprojector

// Retrieve the transformation info to convert from WGS84 (EPSG:4326) to Web Mercator (EPSG:3857)
val transformInfo = Reprojector.findTransformationInfo(4326, 3857)

// Create a test point in EPSG:4326 (Longitude: -117.0, Latitude: 33.0)
val gf = new GeometryFactory()
val point = gf.createPoint(new Coordinate(-117.0, 33.0))

// Apply the transformation
val convertedPoint = Reprojector.reprojectGeometry(point, transformInfo)

val cx = convertedPoint.getCoordinate.x
val cy = convertedPoint.getCoordinate.y

// Verify the coordinates are correctly projected to EPSG:3857
// -117.0 longitude should be approx -13,024,380 meters
// 33.0 latitude should be approx 3,895,303 meters
assert(cx < -13000000 && cx > -13100000, s"Expected X around -13024380, got $cx")
assert(cy > 3800000 && cy < 4000000, s"Expected Y around 3895303, got $cy")

println(s"__CHECK__ findTransformationInfo ${cx},${cy}")

