import edu.ucr.cs.bdlab.beast.indexing.RSGrovePartitioner
import edu.ucr.cs.bdlab.beast.operations.SpatialJoin
import edu.ucr.cs.bdlab.beast.cg.SpatialJoinAlgorithms.ESJPredicate

// The Distributed Join (DJ) algorithm requires both datasets to be spatially partitioned.
// We use RSGrovePartitioner to ensure disjoint partitions and prevent duplicate results.
val partitionedR1 = featuresRDD.spatialPartition(classOf[RSGrovePartitioner])
val partitionedR2 = featuresRDD.spatialPartition(classOf[RSGrovePartitioner])

// Execute the Distributed Join (DJ)
val joinedFeatures = SpatialJoin.spatialJoinDJ(
  partitionedR1, 
  partitionedR2, 
  ESJPredicate.Intersects
)

val joinCount = joinedFeatures.count()
val r1Count = partitionedR1.count()

// Since we are joining the dataset with itself using the Intersects predicate,
// every feature must at least intersect with itself. Therefore, the join count
// must be greater than or equal to the number of features in the original dataset.
assert(joinCount >= r1Count, s"Self-join with Intersects should yield at least $r1Count results, but got $joinCount")

println(s"__CHECK__ spatialJoinDJ $joinCount")

