val tile = rasterRDD.first()

val startY = tile.y1
val endY = tile.y2
val startX = tile.x1
val endX = tile.x2

var definedCount = 0
var undefinedCount = 0
var sumValues = 0.0f

// Iterate over all pixels in the tile's bounding box using its global coordinates
for (y <- startY to endY; x <- startX to endX) {
  if (tile.isDefined(x, y)) {
    definedCount += 1
    sumValues += tile.getPixelValue(x, y)
  } else {
    undefinedCount += 1
  }
}

val totalGridPixels = (endY - startY + 1) * (endX - startX + 1)

// Verify that the iteration bounds exactly match the expected grid capacity
assert(definedCount + undefinedCount == totalGridPixels, 
  s"Total pixels checked (${definedCount + undefinedCount}) does not match grid size ($totalGridPixels)")
assert(startY <= endY, s"y1 ($startY) must be <= y2 ($endY)")

println(s"__CHECK__ y1 $startY")
